#include "mac.h"

void mac(hls::stream<data_t> &in, hls::stream<acc_t> &out, const data_t coef[N_TAPS]) {
#pragma HLS INTERFACE axis port=in
#pragma HLS INTERFACE axis port=out
#pragma HLS ARRAY_PARTITION variable=coef complete dim=1

    acc_t acc = 0;
    for (int i = 0; i < N_TAPS; i++) {
#pragma HLS PIPELINE II=1
        data_t x = in.read();
        acc += x * coef[i];
    }
    out.write(acc);
}

#ifndef MAC_H
#define MAC_H

#include "ap_fixed.h"
#include "hls_stream.h"

#define N_TAPS 8

typedef ap_fixed<16, 8> data_t;
typedef ap_fixed<32, 16> acc_t;

void mac(hls::stream<data_t> &in, hls::stream<acc_t> &out, const data_t coef[N_TAPS]);

#endif

#include <cmath>
#include <cstdio>

#include "mac.h"

int main() {
    const double coef_d[N_TAPS] = {0.5, -0.25, 1.0, 0.125, -1.5, 0.75, 2.0, -0.0625};
    const double in_d[N_TAPS] = {1.0, 2.0, -3.0, 4.5, 0.25, -1.75, 8.0, 3.125};

    data_t coef[N_TAPS];
    hls::stream<data_t> in;
    hls::stream<acc_t> out;

    double expected = 0.0;
    for (int i = 0; i < N_TAPS; i++) {
        coef[i] = coef_d[i];
        in.write(data_t(in_d[i]));
        expected += in_d[i] * coef_d[i];
    }

    mac(in, out, coef);

    acc_t got = out.read();
    double got_d = got.to_double();
    double err = std::fabs(got_d - expected);
    std::printf("expected=%f got=%f err=%f\n", expected, got_d, err);
    if (err > 1e-3) {
        std::printf("FAIL\n");
        return 1;
    }
    std::printf("PASS\n");
    return 0;
}

